Ext.define('BNK.view.BackOffice.bom.BomTasPushBoxMViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BomTasPushBoxMViewController',

    config: {
        viewId: 'BomTasPushBoxM'
    },

    /* 알림함 조회 */
    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            store = vm.storeInfo.PushStore;

        store.removeAll();
        store.loadPage(1);
    },

    onRedirectPage: function(view) {
        var me = this,
            refs = me.getReferences(),
            vm = me.getViewModel(),
            naviView = me.getView().up('navigationview');

        me.PUSH_VIEW(naviView,{
            menuId : view.viewId
        });
    },

    fnReadAllPush: function() {
        var me = this;
        var refs = me.getReferences();

        var pushList = [];
        var records = refs.pushGrid.getJsonAllRecords();
        for(var i = 0; i < records.length; i++){
            if(records[i].rvStcd != Constants.rvStcdType.RV_COMPLETE){
                pushList.push(records[i]);
            }
        }

        if(pushList.length <= 0){
            Ext.Msg.alert('알림', '이미 모든 알림이 읽음 처리 되었습니다.');
            return;
        }

        var values = {
            pushList : pushList
        };

        // saveAllPushRvStcd
        Ext.Ajax.request({
            headers : {
                serviceId : 'BomTasSvc.saveAllPushRvStcd',
                viewId : me.getViewId(),
                scope : me,
            },
            jsonData : values,
            success : function(response) {
                Ext.Msg.alert('알림', '모두 읽음 처리 되었습니다.');
                me.onSelect();
            }
        });
    },

    /* 알림설정 */
    onBtnReadAll: function(button, e, eOpts) {
        var me = this,
            naviView = me.getView().up('navigationview');

        Ext.Msg.confirm('확인', '모든 알림을 읽음 처리 하시겠습니까?',function(btn){
            switch(btn){
                case 'yes':
                me.fnReadAllPush();
                break;
                default :
                return;
            }
        });
    },

    /* 알림설정 */
    onBtnPushSetting: function(button, e, eOpts) {
        var me = this,
            naviView = me.getView().up('navigationview');

        me.PUSH_VIEW(naviView, {
            menuId : 'BomTasPushSettingM',
            title : '알림설정',
            isSubView : true
        });
    },

    /* 알림상세(팝업) */
    onGridSelect: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            msgChkActDvcd = selected[0].data.msgChkActDvcd;

        var win = null;
        if (msgChkActDvcd) {
            if(msgChkActDvcd == Constants.msgChkActDvcd.NORMAL) {
                // 일반
                win = Ext.create('BomTasPushDetailPopupM', {boTasmTrsId : selected[0].data.boTasmTrsId, refresh : true});

                me.mon(win, 'refresh', function() {
                    me.onSelect();
                }, me);

                me.mon(win, 'redirect', function(viewId){
                    me.onRedirectPage(viewId);
                });

                win.show();
            } else if(msgChkActDvcd == Constants.msgChkActDvcd.APPROVAL) {
                // 결재
                win = Ext.create('BomTasPushDetailPopupM', {boTasmTrsId : selected[0].data.boTasmTrsId, refresh : true});
                me.mon(win, 'refresh', function() {
                    me.onSelect();
                }, me);
                win.show();
            }
        }
    },

    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        refs.pushGrid.el.select('.x-headercontainer').setStyle('height', '0px');

        me.onSelect();
    }

});